const AWS = require('aws-sdk');
const fs = require('fs');
const path = require('path');
const tf = require('@tensorflow/tfjs-node'); // For TensorFlow models
const { v4: uuidv4 } = require('uuid'); // For caching

// Load the model once when the Lambda function starts
let model = null;
const MODEL_PATH = process.env.MODEL_PATH;

// Load the model asynchronously
async function loadModel() {
  if (model) return model;

  const modelPath = path.join(__dirname, '..', 'model', 'model.pb');
  const modelJsonPath = path.join(__dirname, '..', 'model', 'model.json');

  // Load the model architecture and weights
  const model = await tf.loadLayersModel(
    tf.io.fileSystem(modelPath, {
      modelJsonPath: modelJsonPath,
    })
  );

  // Compile the model if needed
  // model.compile({ optimizer: 'adam', loss: 'meanSquaredError' });

  return model;
}

// Cache predictions to avoid reprocessing the same input
const predictionCache = new Map();

// Main Lambda handler
exports.main = async (event) => {
  try {
    // Load the model if not already loaded
    model = await loadModel();

    // Parse the request body
    const body = JSON.parse(event.body);
    const input = body.input;

    // Check if the input is already cached
    const cacheKey = JSON.stringify(input);
    if (predictionCache.has(cacheKey)) {
      return {
        statusCode: 200,
        body: JSON.stringify({ prediction: predictionCache.get(cacheKey) }),
      };
    }

    // Convert input to a TensorFlow tensor
    const tensor = tf.tensor(input, [1, input.length]);

    // Make the prediction
    const prediction = await model.predict(tensor);

    // Convert the prediction to a JavaScript array
    const predictionArray = prediction.arraySync().flat();

    // Cache the result
    predictionCache.set(cacheKey, predictionArray);

    // Return the response
    return {
      statusCode: 200,
      body: JSON.stringify({ prediction: predictionArray }),
    };
  } catch (error) {
    console.error('Error during prediction:', error);
    return {
      statusCode: 500,
      body: JSON.stringify({ error: 'Internal Server Error' }),
    };
  }
};
```

